// Kian OS GUI - embedded bitmap fonts (generated by scripts/gen_font.py,
// do not edit by hand). UI font: Liberation Sans 16px em (18 rows,
// proportional). Mono font: DejaVu Sans Mono 13px in an 8x16 cell.
// 1 bit per pixel, MSB = leftmost pixel. ASCII 32..126 only.
#pragma once
#include <kian_abi.h>

const int FONT_UI_ROWS = 18;          // em rows, UI font
const int FONT_MONO_ROWS = 16;      // em rows, mono font
const int FONT_MONO_CELL = 8; // advance of every mono glyph
const int FONT_UI_CAP_TOP = 1;     // first ink row of A-Z0-9 (UI font)
const int FONT_UI_CAP_BOT = 12;     // last ink row of A-Z0-9 (UI font)
const int FONT_MONO_CAP_TOP = 2;
const int FONT_MONO_CAP_BOT = 10;

struct GlyphBits {
    int adv;          // advance in px (scale 1)
    int w;            // ink width in px (scale 1)
    int rows;         // em rows
    const uint8_t *bits;  // rows x 2 bytes, MSB-left
};

bool font_glyph_ui(char c, GlyphBits *out);    // proportional UI font
bool font_glyph_mono(char c, GlyphBits *out);  // 8x16 terminal font
